// 渲染中心区域弃牌
function renderCenterDiscarded() {
    if (!gameState || !gameState.playerInfo) return;

    let mySeatNum = 1;
    if (playerId && gameState.playerInfo[playerId]) {
        mySeatNum = gameState.playerInfo[playerId].seatNum;
    }

    // 屏幕位置映射：下=自己, 右=下家, 上=对家, 左=上家
    const zoneMap = {
        0: 'discardedBottom',  // 自己 -> 下方弃牌区
        1: 'discardedRight',   // 下家 -> 右侧弃牌区
        2: 'discardedTop',     // 对家 -> 上方弃牌区
        3: 'discardedLeft'     // 上家 -> 左侧弃牌区
    };

    // 先清空所有弃牌区
    Object.values(zoneMap).forEach(id => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = '';
    });

    for (let seatNum = 1; seatNum <= 4; seatNum++) {
        const relativePos = (seatNum - mySeatNum + 4) % 4;
        const zoneId = zoneMap[relativePos];
        const zoneEl = document.getElementById(zoneId);
        if (!zoneEl) continue;

        // 找到该座位的玩家
        for (const [pid, info] of Object.entries(gameState.playerInfo)) {
            if (info.seatNum !== seatNum) continue;

            const cards = info.discardedCards || [];
            cards.forEach(card => {
                const div = document.createElement('div');
                div.className = 'discarded-card';
                // 使用图片显示弃牌
                const imgPath = getTileImagePath(card);
                if (imgPath) {
                    div.innerHTML = `<img src="${imgPath}" alt="${getCardDisplayName(card)}" style="width:100%;height:100%;object-fit:contain;border-radius:1px;">`;
                    div.style.background = '#f5f5f0';
                }
                zoneEl.appendChild(div);
            });
            break;
        }
    }
}

